      name: isChineseDisplayLanguage() ? "\u672C\u5730\u5316\u5F53\u524D\u7B14\u8BB0\u9644\u4EF6\uFF08Obsidian \u4F4D\u7F6E\uFF09" : "Localize attachments for the current note (Obsidian location)",
